/// Runtime identity of the backend this detector actually holds.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn hacienda_ner_detector_runtime_state(this: AlefHandle) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<hacienda::pii::NerDetector>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return 0;
        }
        let obj_ptr = match locked_handle_ptr::<hacienda::pii::NerDetector>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &*obj_ptr };

        let result = obj.runtime_state();
        match insert_handle(result) {
            Ok(handle) => handle,
            Err(error) => {
                set_handle_error(&error);
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

/// Drop entities the backend scores below `threshold`.
///
/// Entities without a confidence score are kept: a backend that does not report
/// confidence should not be silently filtered to nothing.
///
/// # Candle GLiNER threshold floor
///
/// `xberg::text::ner::candle::CandleBackend::detect` hard-codes an internal
/// threshold of `0.5` before `NerDetector`'s own filter runs. Consequently
/// `with_threshold` can only ever *raise* the effective threshold above `0.5`;
/// it can never lower it. Entities the Candle backend scores below `0.5` are
/// invisible at any configured threshold, so every recall figure measured
/// through this detector is *truncated recall at 0.5*, not recall. This is an
/// upstream xberg limitation, not something this crate can work around without
/// patching `CandleBackend::detect`.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn hacienda_ner_detector_with_threshold(this: AlefHandle, threshold: f32) -> AlefHandle {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = Vec::new();
        if __alef_requests.iter().any(|request| request.handle == this) {
            set_handle_error(&HandleError::AliasedHandle);
            return 0;
        }
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return 0;
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return 0;
        }
        if __alef_values.iter().any(|(handle, _)| *handle == this) {
            set_handle_error(&HandleError::AliasedHandle);
            return 0;
        }
        let obj = match take_handle::<hacienda::pii::NerDetector>(this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return 0;
            }
        };

        let threshold_rs = threshold;

        let result = obj.with_threshold(threshold_rs);
        match insert_handle(result) {
            Ok(handle) => handle,
            Err(error) => {
                set_handle_error(&error);
                0
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            0
        }
    }
}

