/// Find every non-overlapping PII span in `text`, ordered by start offset.
///
/// When two patterns match overlapping spans the earlier-starting match wins;
/// ties are broken by the pattern order in `builtin_patterns`.
///
/// A pattern with a `PatternMeta.validator` has its matched text checked before
/// being kept: `Some(false)` drops the match entirely (e.g. a 16-digit run that fails
/// Luhn is not a credit card), `Some(true)` promotes its confidence to `1.0`, and
/// `None` keeps `PatternMeta.base_confidence` as-is. Patterns with no validator are
/// unaffected â same `base_confidence` (`1.0` unless calibrated lower) every match.
/// \note SAFETY: Caller must ensure all pointer arguments are valid or null. Returned pointers must be
/// freed with the appropriate free function.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn hacienda_regex_engine_find_all(
    this: AlefHandle,
    text: *const std::ffi::c_char,
) -> *mut std::ffi::c_char {
    clear_last_error();
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut __alef_requests: Vec<HandleRequest> = [Some(HandleRequest {
            handle: this,
            expected_type: std::any::TypeId::of::<hacienda::pii::RegexEngine>(),
        })]
        .into_iter()
        .flatten()
        .collect();
        let __alef_values = match acquire_handles(&__alef_requests) {
            Ok(values) => values,
            Err(error) => {
                set_handle_error(&error);
                return std::ptr::null_mut();
            }
        };
        let mut __alef_guards = Vec::with_capacity(__alef_values.len());
        for (handle, value) in &__alef_values {
            match value.lock() {
                Ok(guard) => __alef_guards.push((*handle, guard)),
                Err(_) => {
                    set_handle_error(&HandleError::RegistryPoisoned);
                    return std::ptr::null_mut();
                }
            }
        }
        if this == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return std::ptr::null_mut();
        }
        let obj_ptr = match locked_handle_ptr::<hacienda::pii::RegexEngine>(&mut __alef_guards, this) {
            Ok(value) => value,
            Err(error) => {
                set_handle_error(&error);
                return std::ptr::null_mut();
            }
        };
        // SAFETY: the registry entry guard remains held for the duration of this call.
        let obj = unsafe { &*obj_ptr };

        if text.is_null() {
            set_last_error(1, "Null pointer passed for parameter 'text'");
            return std::ptr::null_mut();
        }
        // SAFETY: null check above guarantees text is a valid pointer; string is valid UTF-8 from caller.
        let text_rs = match unsafe { CStr::from_ptr(text) }.to_str() {
            Ok(s) => s.to_string(),
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in parameter 'text'");
                return std::ptr::null_mut();
            }
        };

        let result = obj.find_all(&text_rs);
        match serde_json::to_string(&result) {
            Ok(s) => match CString::new(s) {
                Ok(cs) => cs.into_raw(),
                Err(_) => {
                    set_last_error(
                        ALEF_FFI_CONVERSION_ERROR,
                        "FFI JSON value contains an interior NUL byte",
                    );
                    std::ptr::null_mut()
                }
            },
            Err(_) => {
                set_last_error(ALEF_FFI_CONVERSION_ERROR, "failed to serialize FFI field value");
                std::ptr::null_mut()
            }
        }
    })) {
        Ok(value) => value,
        Err(_) => {
            // A panic can unwind past code that already reported a more specific error via
            // set_last_error/set_handle_error (e.g. a conversion failure right before an
            // unrelated panic deeper in the same call); only stamp the generic panic marker
            // when nothing more specific is already recorded, so that context survives.
            if LAST_ERROR_CODE.with_borrow(|c| *c == 0) {
                let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(set_panic_error));
            }
            std::ptr::null_mut()
        }
    }
}

