/// with `hacienda_builtin_patterns`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn hacienda_builtin_patterns_len() -> usize {
    catch_ffi_panic_preserving_error(0, || last_return_len("hacienda_builtin_patterns"))
}

